#!/usr/bin/env node
/* Number words 0–100 for the 3D hall («Сандар қаласы») from web/data.js numToKk — the engine is the only source.
 * Usage: node tools/build-numbers.js   (suite/src/lib/sandar.test.ts checks the file against the engine) */
const fs = require('fs'), path = require('path');
global.window = {}; require('../web/data.js');
const words = Array.from({ length: 101 }, (_, n) => window.QDATA.numToKk(n));
fs.writeFileSync(path.join(__dirname, '../suite/src/data/numberWords.ts'),
  '/* GENERATED by tools/build-numbers.js from web/data.js numToKk — do not edit by hand. */\nexport const NUMBER_WORDS: string[] = ' + JSON.stringify(words) + ';\n');
console.log('numberWords.ts: 0–100');
